"""Writes a C++ header with files as string constants.

  embed_resources.py <out.h> <kName>=<file> ...

Koan's WebUI pages are a few small files; embedding them avoids adding a
grit target and a .pak to upstream's resource lists.
"""

import os
import sys

DELIMITER = 'koan_resource'


def main(argv):
  out, entries = argv[1], argv[2:]
  guard = os.path.basename(out).upper().replace('.', '_') + '_'
  lines = [
      '// Generated by koan/browser/ui/webui/embed_resources.py. Do not edit.',
      f'#ifndef KOAN_BROWSER_UI_WEBUI_{guard}',
      f'#define KOAN_BROWSER_UI_WEBUI_{guard}',
      '',
      'namespace koan {',
      '',
  ]
  for entry in entries:
    name, path = entry.split('=', 1)
    with open(path, encoding='utf-8') as f:
      data = f.read()
    if f'){DELIMITER}"' in data:
      sys.exit(f'{path} contains the raw string delimiter')
    lines.append(
        f'inline constexpr char {name}[] = R"{DELIMITER}({data}){DELIMITER}";')
    lines.append('')
  lines += ['}  // namespace koan', '', f'#endif  // KOAN_BROWSER_UI_WEBUI_{guard}', '']
  with open(out, 'w', encoding='utf-8') as f:
    f.write('\n'.join(lines))


if __name__ == '__main__':
  main(sys.argv)
